"use strict";(self.webpackChunkmantis_docs=self.webpackChunkmantis_docs||[]).push([[95],{7194:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>a,default:()=>d,frontMatter:()=>s,metadata:()=>r,toc:()=>h});var o=n(4848),i=n(8453);const s={sidebar_position:1},a="The Mantis Rollup",r={id:"rollup/mantis",title:"The Mantis Rollup",description:"A core component of Mantis is the Mantis rollup. Previously, rollups have been limited to the optimistic or ZK rollups in the Ethereum ecosystem. To meet its own unique needs, Mantis created its own rollup design on Solana.",source:"@site/docs/rollup/mantis.md",sourceDirName:"rollup",slug:"/rollup/mantis",permalink:"/rollup/mantis",draft:!1,unlisted:!1,editUrl:"https://github.com/ComposableFi/mantis-docs/docs/rollup/mantis.md",tags:[],version:"current",sidebarPosition:1,frontMatter:{sidebar_position:1},sidebar:"rollup",next:{title:"Bridge Contract",permalink:"/rollup/bridge-contract"}},l={},h=[{value:"Solana IBC",id:"solana-ibc",level:3},{value:"Alternative Proofs",id:"alternative-proofs",level:3},{value:"Security and Validation from the Solana L1",id:"security-and-validation-from-the-solana-l1",level:3},{value:"Instant Withdrawals - Avoiding the 7 Day Challenge Window",id:"instant-withdrawals---avoiding-the-7-day-challenge-window",level:3}];function c(e){const t={a:"a",em:"em",h1:"h1",h3:"h3",header:"header",img:"img",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"the-mantis-rollup",children:"The Mantis Rollup"})}),"\n",(0,o.jsx)(t.p,{children:"A core component of Mantis is the Mantis rollup. Previously, rollups have been limited to the optimistic or ZK rollups in the Ethereum ecosystem. To meet its own unique needs, Mantis created its own rollup design on Solana."}),"\n",(0,o.jsx)(t.p,{children:"In this design, the bridge contract is used to move assets between Solana and Mantis. A relayer is also used to send information between these two ecosystems:"}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"nymph",src:n(729).A+"",width:"786",height:"768"})}),"\n",(0,o.jsx)(t.p,{children:"We are pleased to be introducing the first rollup on Solana in the form of the Mantis rollup. We hope that this can set a new standard to introduce the benefits of rollups to the Solana ecosystem. As a result, Solana-based applications and frameworks can be more performant and scalable. Moreover, the user experience can be improved through increased security and speed as well as reduced cost."}),"\n",(0,o.jsx)(t.p,{children:"The Mantis rollup\u2019s core role is to be a coordination and settlement layer for cross-domain, intent-based mechanisms of the Mantis protocol. The Mantis rollup also provides a framework for block proposals and credible commitments across domains. These commitments are held accountable through IBC\u2019s security model, ensuring transparency and trust in multi-chain interactions."}),"\n",(0,o.jsx)(t.p,{children:"Components of the Mantis rollup are depicted in the following diagram:"}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.img,{alt:"praying",src:n(4815).A+"",width:"1600",height:"966"})}),"\n",(0,o.jsx)(t.h1,{id:"our-unique-svm-rollup-approach",children:"Our Unique SVM Rollup Approach"}),"\n",(0,o.jsx)(t.h3,{id:"solana-ibc",children:"Solana IBC"}),"\n",(0,o.jsxs)(t.p,{children:["The Mantis rollup makes use of the ",(0,o.jsx)(t.a,{href:"https://www.picasso.network/",children:"Picasso Network\u2019s"})," ",(0,o.jsx)(t.a,{href:"https://docs.picasso.network/technology/ibc/solana",children:"Solana IBC"})," connection. This connection links Solana to the ",(0,o.jsx)(t.a,{href:"https://docs.picasso.network/technology/ibc/solana",children:"Inter-Blockchain Communication (IBC) Protocol"}),". IBC is a protocol for trust-minimized cross-chain communication. Initially, IBC was created to connect the ",(0,o.jsx)(t.a,{href:"https://hub.cosmos.network/",children:"Cosmos Hub"})," and ",(0,o.jsx)(t.a,{href:"https://v1.cosmos.network/sdk",children:"Cosmos SDK"})," chains. Picasso has expanded IBC to connect ",(0,o.jsx)(t.a,{href:"https://ethereum.org/en/",children:"Ethereum"})," and ",(0,o.jsx)(t.a,{href:"https://solana.com/",children:"Solana"}),", with plans for connecting other protocols like Bitcoin in the future."]}),"\n",(0,o.jsx)(t.p,{children:"Solana IBC in particular is used on Mantis to settle transactions down from the Mantis rollup to its layer 1 chain, Solana."}),"\n",(0,o.jsx)(t.p,{children:"Data that is posted to the L1 includes:"}),"\n",(0,o.jsxs)(t.ul,{children:["\n",(0,o.jsx)(t.li,{children:"The block header"}),"\n",(0,o.jsx)(t.li,{children:"The trie root commitment"}),"\n"]}),"\n",(0,o.jsxs)(t.p,{children:["The \u201cguest blockchain\u201d approach enables Solana IBC. We have already reported upon our guest blockchain design in detail ",(0,o.jsx)(t.a,{href:"https://research.composable.finance/t/crossing-the-cross-blockchain-interoperability-chasm/33",children:"here"})," and ",(0,o.jsx)(t.a,{href:"https://research.composable.finance/t/how-the-guest-blockchain-for-solana-ibc-differs-from-a-solo-machine-solution/317",children:"here"}),". The guest blockchain was developed in conjunction with our collaborators on the research team at ",(0,o.jsx)(t.a,{href:"https://www.dpss.inesc-id.pt/",children:"INESC-ID Distributed Systems Group"}),", associated with the University of Lisbon."]}),"\n",(0,o.jsxs)(t.p,{children:["To summarize, this design includes the creation of a new blockchain (the ",(0,o.jsx)(t.em,{children:"guest blockchain"}),") that functions atop a non-IBC-compatible chain (the ",(0,o.jsx)(t.em,{children:"host blockchain"}),"). The guest blockchain functions similarly to a layer 2 of the underlying host chain, but meets all IBC requirements by implementing state proofs. Thus, the host chain is able to interoperate with the IBC via the guest chain. Initially, we have implemented this approach for the Solana blockchain."]}),"\n",(0,o.jsx)(t.h3,{id:"alternative-proofs",children:"Alternative Proofs"}),"\n",(0,o.jsx)(t.p,{children:"The guest blockchain solution is quite developmentally intensive, and must be customized for each chain and whatever IBC requirements the chain is missing. Thus, we have sought a means to replicate state proofs on the SVM itself (including on the Mantis rollup). We do not use ZK or Optimistic proofs, instead creating our own approach. We use the following main mechanisms to deliver IBC-compatible proofs on Solana:"}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.strong,{children:"The Accounts Delta Hash:"})}),"\n",(0,o.jsxs)(t.p,{children:["This alternative proof system uses Solana\u2019s accounts delta Merkle tree. The tree stores all accounts which have changed within a particular Solana slot. This enables proof generation of an account's value whenever it changes. The commitment of the accounts delta tree (an ",(0,o.jsx)(t.em,{children:"accounts delta hash"}),") is encoded within Solana\u2019s bankhash which allows light clients to verify such proofs."]}),"\n",(0,o.jsx)(t.p,{children:"However, this process alone is not enough. If an account hasn\u2019t changed, it\u2019s not possible to prove the account\u2019s value. Moreover, it is inefficient to have to create a new Program Derived Addressaccount (PDA) for each key-value pair an IBC module might need to store."}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.strong,{children:"A Witnessed Trie:"})}),"\n",(0,o.jsx)(t.p,{children:"Therefore, we also introduce an on-chain, witnessed sealable trie. This is the same trie we leverage in the guest blockchain solution. This trie offers state proofs. Therefore, the only remaining factor needed for finality is this trie\u2019s state commitment. To address this, we introduce a witness account storing state commitment that stays in sync with the trie. As a result, the trie\u2019s state commitment is provable via the account\u2019s delta hash."}),"\n",(0,o.jsxs)(t.p,{children:["By combining these components, we have created an alternative proof that meets the state proof requirements of the IBC. Thus, the SVM rollup is able to have finality. For more technical details on this alternative proof mechanism, reference ",(0,o.jsx)(t.a,{href:"https://research.composable.finance/t/mantis-svm-rollup/333",children:"this research forum post by Micha\u0142 Nazarewicz"}),"."]}),"\n",(0,o.jsx)(t.h3,{id:"security-and-validation-from-the-solana-l1",children:"Security and Validation from the Solana L1"}),"\n",(0,o.jsx)(t.p,{children:"True rollups are able to deliver the same security guarantees of their underlying L1. Without this characteristic, the Mantis rollup would simply be a sidechain and it would not inherit the security of Solana. This would have meant we would have needed to bootstrap our own security system. Instead, we implement all rollup requirements into the Mantis L2, including censorship resistance and forced withdrawals. This is accomplished via the IBC: we post proofs down to Solana from the Mantis rollup via IBC, and these proofs are verified by validators on our guest blockchain. As a result, the Mantis rollup is validated by guest blockchain validators, inheriting Solana\u2019s security."}),"\n",(0,o.jsx)(t.h3,{id:"instant-withdrawals---avoiding-the-7-day-challenge-window",children:"Instant Withdrawals - Avoiding the 7 Day Challenge Window"}),"\n",(0,o.jsx)(t.p,{children:"Another benefit of using IBC for our rollup is that we can avoid the lengthy challenge window that most rollups require."}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.a,{href:"https://community.optimism.io/docs/protocol/2-rollup-protocol/#fault-proofs",children:"As per Optimism"}),","]}),"\n",(0,o.jsx)(t.p,{children:(0,o.jsx)(t.em,{children:'\u201cIn an Optimistic Rollup, state commitments are published to L1 (Ethereum in the case of OP Mainnet) without any direct proof of the validity of these commitments. Instead, these commitments are considered pending for a period of time (called the "challenge window"). If a proposed state commitment goes unchallenged for the duration of the challenge window (currently set to 7 days), then it is considered final. Once a commitment is considered final, smart contracts on Ethereum can safely accept withdrawal proofs about the state of OP Mainnet based on that commitment.\u201d'})}),"\n",(0,o.jsx)(t.p,{children:"While they are important for ensuring validity, the 7 day challenge window of ORs causes significant delays in transaction processing. Therefore, it is advantageous for us to shorten this processing time on the Mantis rollup. We are able to omit having a challenge window on the Mantis rollup, as using IBC allows us to inherit the security and validation from the Solana L1."}),"\n",(0,o.jsx)(t.h1,{id:"privacy",children:"Privacy"}),"\n",(0,o.jsx)(t.p,{children:"On Mantis, we use a validator client to make order flow private. To continue to preserve the privacy of intents, we then run the auction to determine the winning solution within the mempool of the sequencer. Here, the intent is exposed to solvers competing to provide the best solution."}),"\n",(0,o.jsx)(t.p,{children:"The only other entity that can see intents is the lead sequencer. On the Solana blockchain, the lead sequencer is a predetermined validator. Since there will initially only be one validator on the Mantis rollup, we can be the only lead sequencer and we will be able to preserve the privacy of transactions. This protects against frontrunning and other malicious forms of MEV that can result from transactions not being private. In the future, we will take a more decentralized approach to this process."})]})}function d(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},4815:(e,t,n)=>{n.d(t,{A:()=>o});const o=n.p+"assets/images/components-19cd9107bb8b3ebd3b6bdc65c6cec0ad.png"},729:(e,t,n)=>{n.d(t,{A:()=>o});const o=n.p+"assets/images/rollup-0861f3e401ee6092cbe177765affa36e.png"},8453:(e,t,n)=>{n.d(t,{R:()=>a,x:()=>r});var o=n(6540);const i={},s=o.createContext(i);function a(e){const t=o.useContext(s);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);